Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>

#define mp make_pair
#define pb push_back
#define ll long long

using namespace std;

const int MOD = 1E9+7;

int parent[1111111];
int nc;

int find( int x ) {
	if ( x == parent[x] ) return x;
	return parent[x] = find(parent[x]);
}

void merge(int a, int b) {
	a = find(a); b = find(b);
	if ( a == b ) return;
	nc --;
	parent[b] = a;
}

ll fmp(ll x, int e) {
	if ( e == 0 ) return 1;
	ll w = fmp(x, e/2);
	w = (w * w) % MOD;
	if ( e&1 ) w = (w * x) % MOD;
	return w;
}

int main() {

	cin.tie(0);
	ios_base::sync_with_stdio(0);

	ll p, k;

	cin >> p >> k;

	if ( k == 0 ) {
		cout << fmp(p, p - 1) << '\n';
		return 0;
	}

	nc = p - (k > 1);

	for ( ll i = 1; i < p; i ++ ) parent[i] = i;

	for ( ll i = 1; i < p; i ++ )
		merge ( i, (i * k) % p );

	cout << fmp ( p, nc ) << '\n';

	return 0;
}


